<template>
  <div class="container q-pa-xl">
    <div class="q-gutter-y-md">
      <div class="full-width">
        <q-markup-table>
          <thead>
            <tr class="highlighted-back">
              <th class="text-h4 text-uppercase">
                {{ $t('fields') }}
              </th>
              <th class="text-h4 text-uppercase text-center">
                {{ $t('requierd') }}
              </th>
              <th class="text-h4 text-uppercase text-center">
                {{ $t('read_only') }}
              </th>
              <th class="text-h4 text-uppercase text-center">
                {{ $t('hidden') }}
              </th>
              <th class="text-h4 text-uppercase text-center">
                {{ $t('force') }}
              </th>
              <th class="text-h4 text-uppercase col-100">
                {{ $t('ocr') }}
              </th>
              <th class="text-h4 text-uppercase col-100">
                {{ $t('match_score') }}
              </th>
              <th class="text-h4 text-uppercase">
                {{ $t('formula') }}
              </th>
            </tr>
            <tr class="highlighted-back">
              <th></th>
              <th class="text-center">
                <q-checkbox :disable="isReadOnly" v-model="is_required" />
              </th>
              <th class="text-center">
                <q-checkbox :disable="isReadOnly" v-model="is_readonly" />
              </th>
              <th class="text-center">
                <q-checkbox :disable="isReadOnly" v-model="is_hidden" />
              </th>
              <th class="text-center">
                <q-checkbox :disable="isReadOnly" v-model="force_validation" />
              </th>
              <th class="col-100"></th>
              <th colspan="2"></th>
            </tr>
          </thead>
          <tbody>
            <template v-for="group in apiData" :key="group.name">
              <tr class="row-header">
                <td class="text-h4 secondary-c-text" colspan="6">
                  {{ $t(group.translation_key) === group.translation_key ? group.title : $t(group.translation_key) }}
                </td>
                <td colspan="2"></td>
              </tr>

              <template v-for="(rows, index) in group.rows" :key="index">
                <tr v-for="row in rows" :key="row.field_name">
                  <td class="text-h4">
                    <q-input
                      :disable="isReadOnly"
                      filled
                      style="background: transparent"
                      v-model="row.field_display_label"
                      :label="row.field_name"
                    />
                  </td>
                  <td class="text-h4 text-center">
                    <q-checkbox
                      :disable="isReadOnly"
                      v-model="row.is_required"
                    />
                  </td>
                  <td class="text-h4 text-center">
                    <q-checkbox
                      :disable="isReadOnly"
                      v-model="row.is_readonly"
                    />
                  </td>
                  <td class="text-h4 text-center">
                    <q-checkbox :disable="isReadOnly" v-model="row.is_hidden" />
                  </td>
                  <td class="text-h4 text-center">
                    <q-checkbox
                      :disable="isReadOnly"
                      v-model="row.force_validation"
                    />
                  </td>
                  <td class="text-h4 text col-100">
                    <q-input
                      outlined
                      :disable="isReadOnly"
                      v-model="row.confidence_threshold"
                    />
                  </td>
                  <td class="text-h4 text col-100">
                    <q-input
                      outlined
                      :disable="isReadOnly"
                      v-model="row.match_score_threshold"
                    />
                  </td>
                  <td class="text-h4">
                    <q-btn v-if="row['field_org_id'] !== DEFAULT_ORG_UUID" flat>
                      <Icon
                        icon="mdi:text-search"
                        :class="row['fuzzy_field'] ? 'text-primary' : 'text-grey-5'"
                        style="font-size: 30px"
                      />
                    </q-btn>
                  </td>
                </tr>
              </template>
            </template>
          </tbody>
        </q-markup-table>
      </div>

      <div class="row full-width q-mt-sm"></div>
    </div>
