  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';

import type { dynamicObj } from 'src/pages/assets';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { docFieldsApiService, documentDetailApiService } from 'src/services';
import { DEFAULT_ORG_UUID } from 'src/constants';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil],
  components: {
    
    Loader,
  },
  data() {
    return {};
  },

  mounted() {
    this.documentType = this.$route.params.type.toString();
    this.sub_doc_type_key = this.$route.params.sub_doc_type as string;
    this.initView();
  },

  methods: {
    async initView() {
      // await this.setFieldProfile();
      await this.getSettingsByType(true);
    },

    async getSettingsByType(showLoader: boolean) {
      try {
        if (showLoader) {
          this.showLoading();
        }

        const data = Object.assign(this.getDocTypeParams());
        const response = await docFieldsApiService.getFieldSettingsByType(data);
        this.apiData = response.field_setting;
        this.prepareDefaultSettings();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    getDocTypeParams() {
      const data = {} as dynamicObj;
      data['doc_type'] = this.documentType;
      data['is_sub_doc_type'] = 'false';
      return data;
    },

    prepareDefaultSettings() {
      this.is_required = true;
      this.is_readonly = true;
      this.is_hidden = true;
      this.force_validation = true;
      this.confidence_threshold = 0;
      this.match_score_threshold = 0;

      Array.from(this.apiData).forEach((group: any) => {
        Array.from(group.rows).forEach((rows: any) => {
          Array.from(rows).forEach((row: any) => {
            if (this.is_required === true) {
              this.is_required = row.is_required;
            }

            if (this.is_readonly === true) {
              this.is_readonly = row.is_readonly;
            }

            if (this.is_hidden === true) {
              this.is_hidden = row.is_hidden;
            }

            if (this.force_validation === true) {
              this.force_validation = row.force_validation;
            }

            if (row.confidence_threshold > this.confidence_threshold) {
              this.confidence_threshold = row.confidence_threshold;
            }

            if (row.match_score_threshold > this.match_score_threshold) {
              this.match_score_threshold = row.match_score_threshold;
            }

            row.field_display_label = row.field_label ? row.field_label : this.$t(row.translation_key) === row.translation_key ? row.title : this.$t(row.translation_key);
          });
        });
      });
      this.$forceUpdate();
    },

    isFieldHiddenOrReadonly(rowObj: any) {
      if (rowObj.is_readonly || rowObj.is_hidden) {
        this.is_required = false;
        this.force_validation = false;

        rowObj.is_required = false;
        rowObj.force_validation = false;

        return true;
      }

      return false;
    },
  },
  setup() {
    let field_model = {} as { [k: string]: any };
    return {
      filtered_master_fields: ref([] as any),
      field_model: ref(field_model),
      showMasterDataPopup: ref(false),
      apiData: ref(),
      singleField: ref(false),
      allField: ref(false),
      documentType: ref('INVOICE'),
      is_required: ref(false),
      is_readonly: ref(false),
      is_hidden: ref(false),
      force_validation: ref(false),
      confidence_threshold: ref(50),
      match_score_threshold: ref(50),
      showFormulaDlg: ref(false),
      calculation_formula: ref(null),
      sub_doc_type_key: ref(''),
      isReadOnly: ref(true),
      DEFAULT_ORG_UUID,
      profile_options: [
        { label: 'DEFAULT', value: 'DEFAULT' },
        { label: 'ZUGFeRD', value: 'Zugferd' },
      ],
      data_type: [
        { label: 'Select Type', value: '' },
        { label: i18n.t('amount'), value: 'AMOUNT' },
        { label: 'STRING', value: 'STRING' },
        { label: i18n.t('invoice_date'), value: 'DATE' },
        { label: i18n.t('number'), value: 'NUMBER' },
        { label: 'BOOLEAN', value: 'BOOLEAN' },
        { label: i18n.t('currency'), value: 'CURRENCY' },
      ],
    };
  },
});
</script>

