<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import { docFieldsApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { injectCalculatedFields } from 'src/utils/fieldSettingsHelper';
import { charges_table_extraction, CONSTANTS, DEFAULT_ORG_UUID } from 'src/constants';
import parentFields from 'src/pages/Settings/Components/docTypeFields/parentFields.vue';
import {
  useMasterDataLookupStore,
  useDropdownStore,
  useFieldValuesSettingsStore,
  useSettingStore,
} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil],
  components: {
    
    Loader,
    parentFields,
  },
  data() {
    return {
      disable_checkbox: false,
      showChargesElement: ref(false),
      exclude_fields: ['move_all'],
      search: '',
    };
  },
  watch: {
    doc_type_loading: {
      handler: function (newVal, oldVal) {
        this.getParentDocTypeName();
      },
    },
  },
  computed: {
    filteredFieldSettings() {
      if (!this.search) return this.apiData as dynamicObj[];
      const filteredData = [] as dynamicObj[];
      if (this.search) {
        this.apiData.forEach((group: dynamicObj) => {
          const passedGroup = {} as dynamicObj;
          const passedRows = [] as any;
          //check if field name or field display label matches the search
          group.rows.forEach((row: dynamicObj[]) => {
            const passedRow = row.filter((row: dynamicObj) => {
              return (
                row.field_display_label
                  .toLowerCase()
                  .includes(this.search.toLowerCase()) ||
                row.field_name.toLowerCase().includes(this.search.toLowerCase())
              );
            });
            if (passedRow.length > 0) {
              passedRows.push(passedRow);
            }
          });
          //check if any row passed the search
          if (passedRows.length > 0) {
            passedGroup['rows'] = passedRows;
            passedGroup['name'] = group.name;
            passedGroup['translation_key'] = group.translation_key;
            passedGroup['title'] = group.title;
            filteredData.push(passedGroup);
          }
          //check if group title and name matches the search
          if (
            !passedGroup.rows &&
            (group.name.toLowerCase().includes(this.search.toLowerCase()) ||
              group.title.toLowerCase().includes(this.search.toLowerCase()))
          ) {
            filteredData.push({
              rows: passedRows,
              name: group.name,
              translation_key: group.translation_key,
              title: group.title,
            });
          }
        });
      }
      return filteredData;
    },
  },
  mounted() {
    this.documentType = this.$route.params.type.toString();

    this.sub_doc_type_key = this.$route.params.sub_doc_type as string;
    this.initView();
  },
  methods: {
    isFieldSelected() {
      if (Object.keys(this.fields_checkbox).length == 0) return false;
      let isSelected = false;
      for (const [key, value] of Object.entries(this.fields_checkbox)) {
        if (value) {
          isSelected = true;
          break;
        }
      }
      return isSelected;
    },
    async initView() {
      this.getParentDocTypeName();
      // await this.setFieldProfile();
      await this.getSettingsByType(true);
      // await this.getMasterDataTypesAndFields();
      await this.getFieldGroups();
      await this.getLovList();
      this.prepareDataTypeDropdown();

      if (this.user_settings[charges_table_extraction]) {
        this.costingElementList = await this.getCostingElementList([]);
      }
    },

    masterDataSettings() {
      const currentURL = this.$route.path;
      let path = '/master-data';
      if (currentURL.endsWith('/')) {
        path = 'master-data';
      }
      this.$router.push(currentURL + path);
    },

    getParentDocTypeName() {
      if (!this.doc_type_list || !this.sub_doc_type_key) {
        return;
      }

      if (this.parent_doc_type_name) {
        return this.parent_doc_type_name;
      }

      const parent_doc_type = this.doc_type_list.filter(
        (v: any) => v.value.indexOf(this.documentType) > -1,
      );

      if (parent_doc_type.length == 0) {
        return;
      }
      this.parent_doc_type_name = parent_doc_type[0].label;
      return this.parent_doc_type_name;
    },

    async getSettingsByType(showLoader: boolean) {
      try {
        if (showLoader) {
          this.showLoading();
        }

        const data = Object.assign(this.getDocTypeParams());
        const response = await docFieldsApiService.getFieldSettingsByType(data);
        // DK-10: gate calculated_fields injection on org-pref toggle (default OFF).
        const calcEnabled =
          String(
            useSettingStore().org_based_settings?.[
              'INVOICE_CALCULATION_FIELDS_ENABLED'
            ] ?? 'false',
          ) === 'true';
        injectCalculatedFields(response.field_setting, this.documentType, calcEnabled);
        this.apiData = response.field_setting;
        this.prepareDefaultSettings();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    getDocTypeParams(doc_type_field_name = 'doc_type') {
      const data = {} as dynamicObj;
      data[doc_type_field_name] = this.documentType;
      data['is_sub_doc_type'] = 'false';
      if (this.sub_doc_type_key) {
        data[doc_type_field_name] = this.sub_doc_type_key;
        data['is_sub_doc_type'] = 'true';
      }
      return data;
    },

    async save() {
      try {
        this.showLoading();
        const savableData = this.apiData.filter((group: any) => group.name !== 'calculated_fields');
        if (savableData.length === 0) {
          notify.success(this.$t('MSG_SAVE'));
          return;
        }
        const data = { data: JSON.stringify(savableData) };
        const query_data = Object.assign(this.getDocTypeParams());
        await docFieldsApiService.update(data, query_data);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async resetToDefault() {
      try {
        this.showLoading();
        const query_data = Object.assign(this.getDocTypeParams());
        await docFieldsApiService.restoreDefaultFields({}, query_data);
        await this.getSettingsByType(false);
        notify.success(this.$t('SETTING_RESTORED'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    setSetting(settingType: string) {
      let found = false;

      Array.from(this.apiData).forEach((group: any) => {
        Array.from(group.rows).forEach((rows: any) => {
          Array.from(rows).forEach((row: any) => {
            if (settingType === 'is_readonly') {
              row.is_readonly = this.is_readonly;
            } else if (settingType === 'is_hidden') {
              row.is_hidden = this.is_hidden;
            } else if (settingType === 'confidence_threshold') {
              row.confidence_threshold = this.confidence_threshold;
            } else if (settingType === 'match_score_threshold') {
              row.match_score_threshold = this.match_score_threshold;
            } else if (
              settingType === 'is_required' ||
              settingType === 'force_validation'
            ) {
              if (settingType === 'is_required') {
                row.is_required = this.is_required;
              } else if (settingType === 'force_validation') {
                row.force_validation = this.force_validation;
              }
              found = true;
            }
          });
        });
      });
      if (found) {
        notify.error(this.$t('REVIEW_YOUR_SELECTION'));
      }
      this.$forceUpdate();
    },

    resetAllSelection(settingType: string, row: any) {
      if (settingType === 'is_required' && row === false) {
        this.is_required = false;
      } else if (settingType === 'is_readonly' && row === false) {
        this.is_readonly = false;
      } else if (settingType === 'is_hidden' && row === false) {
        this.is_hidden = false;
      } else if (settingType === 'force_validation' && row === false) {
        this.force_validation = false;
      } else if (
        settingType === 'confidence_threshold' &&
        this.confidence_threshold != row
      ) {
        this.confidence_threshold = 50;
      } else if (
        settingType === 'match_score_threshold' &&
        this.match_score_threshold != row
      ) {
        this.match_score_threshold = 50;
      }
    },

    prepareDefaultSettings() {
      this.fields_checkbox['move_all'] = false;
      this.is_required = true;
      this.is_readonly = true;
      this.is_hidden = true;
      this.force_validation = true;
      this.confidence_threshold = 0;
      this.match_score_threshold = 0;

      Array.from(this.apiData).forEach((group: any) => {
        Array.from(group.rows).forEach((rows: any) => {
          Array.from(rows).forEach((row: any) => {
            if (row.is_required == null) row.is_required = false;
            if (row.is_readonly == null) row.is_readonly = false;
            if (row.is_hidden == null) row.is_hidden = false;
            if (row.force_validation == null) row.force_validation = false;
            if (row.confidence_threshold == null) row.confidence_threshold = 50;
            if (row.match_score_threshold == null) row.match_score_threshold = 50;

            if (this.is_required === true) {
              this.is_required = row.is_required;
            }

            if (this.is_readonly === true) {
              this.is_readonly = row.is_readonly;
            }

            if (this.is_hidden === true) {
              this.is_hidden = row.is_hidden;
            }

            if (this.force_validation === true) {
              this.force_validation = row.force_validation;
            }

            if (row.confidence_threshold > this.confidence_threshold) {
              this.confidence_threshold = row.confidence_threshold;
            }

            if (row.match_score_threshold > this.match_score_threshold) {
              this.match_score_threshold = row.match_score_threshold;
            }

            let label = '';
            if (row.translation_key && this.$t(row.translation_key) !== row.translation_key) {
              label = this.$t(row.translation_key);
            } else {
              label = row.title ?? row.field_label;
            }

            row.field_display_label = label;

            if (row['field_org_id'] !== DEFAULT_ORG_UUID) {
              this.fields_checkbox[row.id] = false;
            }

            if (
              row['field_org_id'] == DEFAULT_ORG_UUID &&
              !this.default_fields_groups.includes(group.id)
            ) {
              this.default_fields_groups.push(group.id);
            }
          });
        });
      });

      logInfo(this.default_fields_groups);
      this.$forceUpdate();
    },
    saveNewFieldLabel(row: any) {
      row.field_label = row.field_display_label;
    },
    openCalcDialog(row: any) {
      this.field_model = row as dynamicObj;
      this.showFormulaDlg = true;
    },

    showCreateGroupForm() {
      this.showGroupDetailsForm = true;
      this.resetCreateGroupForm();
    },

    resetCreateGroupForm() {
      this.groupName = '';
      this.groupTitle = '';
    },

    closeGroupDlg() {
      this.showGroupDetailsForm = false;
      this.resetCreateGroupForm();
    },

    validateGroupCreate() {
      let is_valid = true;
      if (this.groupName === '' || this.groupName === null) {
        is_valid = false;
        notify.error(this.$t('NAME_MANDATORY'));
      } else if (this.groupTitle === '' || this.groupTitle === null) {
        is_valid = false;
        notify.error(this.$t('TITLE_MANDATORY'));
      } else if (this.hasWhiteSpace(this.groupName)) {
        is_valid = false;
        notify.error(this.$t('SPACES_NOT_ALLOWED'));
      }

      return is_valid;
    },

    async createGroup() {
      try {
        if (!this.validateGroupCreate()) {
          return;
        }

        this.showLoading();
        const data = {
          title: this.groupTitle,
          group_name: this.groupName,
          doc_type_name: this.sub_doc_type_key
            ? this.sub_doc_type_key
            : this.documentType,
          translation_key: this.groupName,
          is_sub_doc_type_field: this.sub_doc_type_key ? 'true' : 'false',
        };

        const response = await docFieldsApiService.createGroup(data);
        if (response.success === false) {
          throw { message: response.message };
        }

        await this.getSettingsByType(false);
        await this.getFieldGroups();
        this.closeGroupDlg();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    fieldTypeRule(val: string) {
      if (val === null) {
        return 'You must make a selection!';
      }
    },

    showFieldDetailsDlg(groupName: string) {
      this.groupName = groupName;
      this.resetCreateFieldForm();
      this.showFieldDetailsForm = true;
    },

    resetCreateFieldForm() {
      this.fieldType = '';
      this.fieldName = '';
      this.fieldTitle = '';
      this.barcodeType = 'EAN2';
      this.barCodePattern = '';
      this.field_m3Costing = '';
      this.selectedRecordId = '';
      this.field_list_of_values = '';
      this.showChargesElement = false;
    },

    closeFieldDlg() {
      this.showFieldDetailsForm = false;
      this.groupName = '';
      this.resetCreateFieldForm();
    },

    validateFieldCreate() {
      let is_valid = true;
      if (this.fieldName === '' || this.fieldName === null) {
        is_valid = false;
        notify.error(this.$t('NAME_MANDATORY'));
      } else if (this.fieldTitle === '' || this.fieldTitle === null) {
        is_valid = false;
        notify.error(this.$t('TITLE_MANDATORY'));
      } else if (this.fieldType === '' || this.fieldType === null) {
        is_valid = false;
        notify.error(this.$t('FIELD_TYPE_MANDATORY'));
      } else if (this.hasWhiteSpace(this.fieldName)) {
        is_valid = false;
        notify.error(this.$t('SPACES_NOT_ALLOWED'));
      } else if (this.checkFirstLetterIsSpecialOrNumber(this.fieldName)) {
        is_valid = false;
        notify.error(
          this.$t('errors_special_letter_number_not_allowed'),
        );
      }

      if (
        this.fieldType === 'ENUM' &&
        (this.field_list_of_values === '' || this.fieldType === null)
      ) {
        is_valid = false;
        notify.error(this.$t('LIST_OF_VALUES_MANDATORY'));
      } else if (
        this.showChargesElement &&
        (this.field_m3Costing === '' || this.fieldType === null)
      ) {
        is_valid = false;
        notify.error(
          this.$t('LIST_OF_CHARGES_MANDATORY'),
        );
      }

      return is_valid;
    },

    async createFieldInGroup() {
      try {
        if (!this.validateFieldCreate()) {
          return;
        }
        this.showLoading();
        this.showFieldDetailsForm = false;

        let data = {} as any;
        data = {
          title: this.fieldTitle,
          field_name: this.fieldName,
          field_type: this.fieldType,
          group_name: this.groupName,
          list_of_values: this.field_list_of_values,
          costing_element: this.field_m3Costing,
          is_sub_doc_type_field: this.sub_doc_type_key ? 'true' : 'false',
          enforce_list_of_values: this.field_list_of_values ? true : false,
          doc_type_name: this.sub_doc_type_key
            ? this.sub_doc_type_key
            : this.documentType,
        };

        if (this.fieldType === 'BARCODE') {
          const additionalAttributes = {
            barcode_types: this.barcodeType,
            barcode_pattern: this.barCodePattern,
          };

          data.additional_attributes = JSON.stringify(additionalAttributes);
        } else if (
          this.fieldType == CONSTANTS.user ||
          this.fieldType == CONSTANTS.group
        ) {
          data.field_type = 'STRING';
          data.input_type = this.fieldType;
        }

        const response = await docFieldsApiService.createField(data);
        if (response.success === false) {
          throw { message: response.message };
        }

        this.closeGroupDlg();
        this.getSettingsByType(false);
      } catch (err) {
        notify.error(this.$t('fieldname_already_exists'));
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    handleFieldsReset(rowObj: any) {
      setTimeout(() => {
        if (rowObj.is_hidden) {
          rowObj.is_required = false;
          rowObj.force_validation = false;
        }
      }, 0);
    },

    isFieldHiddenOrReadonly(rowObj: any) {
      if (rowObj.is_hidden) {
        return true;
      }

      return false;
    },

    isVisible(row: any) {
      if (!this.sub_doc_type_key) {
        return true;
      }

      if (row.is_sub_doc_type_field && row.is_sub_doc_type_field == true) {
        return true;
      }
      return false;
    },

    async deleteField(row: any, confirmDeletion = false) {
      try {
        if (!confirmDeletion) {
          this.fieldDeleteConfirm = true;
          this.selected_delete_record = row as dynamicObj;
          return;
        }

        this.showLoading();
        const response = await docFieldsApiService.deleteField(
          this.selected_delete_record['id'],
        );
        if (response.success === false) {
          throw { message: response.message };
        }
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
        this.getSettingsByType(true);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    editField(row: any) {
      this.fieldName = row.field_name;
      this.fieldTitle = row.title;
      this.fieldType = row.field_type;
      this.selectedRecordId = row.id;
      this.showFieldDetailsForm = true;
    },

    async getFieldGroups() {
      try {
        this.showLoading();
        const data = this.getDocTypeParams('doc_type_name');

        const response = await docFieldsApiService.getGroupsByDocType(data);
        if (response.success === false) {
          throw { message: response.message };
        }

        response.data.forEach((group: any, index: any) => {
          const item = Object.assign(
            {},
            {
              value: group.id,
              label: this.getGroupTranslation(group),
              group_name: group.group_name,
            },
          );
          this.groups_options.push(item);
          this.all_groups.push(item);
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    getGroupTranslation(group: any) {
      if (this.$t(group.translation_key) === group.translation_key ) {
        return group.title as string;
      }

      return this.$t(group.translation_key);
    },

    updateFieldGroupClicked() {
      const state = this.fields_checkbox['move_all'];
      for (const field_id in this.fields_checkbox) {
        this.fields_checkbox[field_id] = state;
      }
    },

    displayUpdateFieldGroupDialog() {
      // check if any field is selected
      let selected = false;
      for (const field_id in this.fields_checkbox) {
        if (this.exclude_fields.includes(field_id)) {
          continue;
        }

        if (this.fields_checkbox[field_id]) {
          selected = true;
          break;
        }
      }

      if (!selected) {
        notify.error(this.$t('select_fields'));
        return;
      }
      this.updateGroupDialog = true;
    },

    async updateFieldGroups() {
      try {
        if (!this.selected_group_id) {
          notify.error(this.$t('select_group'));
          return;
        }
        this.showLoading();
        let selected_fields = [];
        for (const field_id in this.fields_checkbox) {
          if (this.exclude_fields.includes(field_id)) {
            continue;
          }
          if (this.fields_checkbox[field_id]) {
            selected_fields.push(field_id);
          }
        }

        const data = {
          field_ids: selected_fields.join(),
          group_id: this.selected_group_id,
        };

        const response = await docFieldsApiService.reassignFieldsToGroup(data);
        if (response.success === false) {
          throw { message: response.message };
        }

        await this.getSettingsByType(true);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    filterGroupsEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.groups_options = this.all_groups;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.groups_options = this.all_groups.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    async deleteGroup(group_id: string) {
      try {
        if (!group_id) {
          notify.error('Group not selected');
          return;
        }
        this.showLoading();

        const response = await docFieldsApiService.deleteGroups(group_id);
        if (response.success === false) {
          throw { message: response.message };
        }

        await this.getSettingsByType(true);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    resetCostingElement() {
      this.field_m3Costing = '';
    },
    prepareDataTypeDropdown() {
      this.data_type = [
        { label: this.$t('please_select_type'), value: '' },
        { label: this.$t('amount'), value: 'AMOUNT' },
        { label: 'String', value: 'STRING' },
        { label: this.$t('invoice_date'), value: 'DATE' },
        { label: this.$t('number'), value: 'NUMBER' },
        { label: 'Boolean', value: 'BOOLEAN' },
        { label: this.$t('currency'), value: 'CURRENCY' },
        { label: 'Dropdown', value: 'ENUM' },
        { label: 'LOV', value: 'LOV' },
        { label: 'Barcode', value: 'BARCODE' },
        { label: this.$t('user_dropdown'), value: CONSTANTS.user },
        { label: this.$t('group_dropdown'), value: CONSTANTS.group },
      ];
    },
  },
  setup() {
    const master_data_lookup = useMasterDataLookupStore();
    const { getCostingElementList } = master_data_lookup;

    const dropdown_store = useDropdownStore();
    const { doc_type_list, doc_type_loading } = storeToRefs(dropdown_store);

    let field_model = {} as { [k: string]: any };

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    const field_values_setting_store = useFieldValuesSettingsStore();
    const { getLovList } = field_values_setting_store;
    const { lov_list } = storeToRefs(field_values_setting_store);
    return {
      user_settings,
      groupName: ref(''),
      groupTitle: ref(''),
      fieldName: ref(''),
      fieldTitle: ref(''),
      fieldType: ref(''),
      barcodeType: ref('EAN2'),
      barCodePattern: ref(''),
      selectedRecordId: ref(''),
      showGroupDetailsForm: ref(false),
      showFieldDetailsForm: ref(false),
      lov_list,
      getLovList,
      costingElementList: [] as any,
      getCostingElementList,
      field_m3Costing: ref(''),
      field_list_of_values: ref(''),
      doc_type_loading,
      doc_type_list,
      updateGroupDialog: ref(false),
      filtered_master_fields: ref([] as any),
      selected_group_id: ref(),
      all_groups: ref([] as any),
      groups_options: ref([] as any),
      default_fields_groups: ref([] as any),
      fields_checkbox: ref({} as any),
      field_model: ref(field_model),
      showMasterDataPopup: ref(false),
      apiData: ref([] as any),
      singleField: ref(false),
      allField: ref(false),
      documentType: ref('INVOICE'),
      parent_doc_type_name: ref(''),
      is_required: ref(false),
      is_readonly: ref(false),
      is_hidden: ref(false),
      force_validation: ref(false),
      confidence_threshold: ref(50),
      match_score_threshold: ref(50),
      showFormulaDlg: ref(false),
      calculation_formula: ref(null),
      sub_doc_type_key: ref(''),
      tab: ref('fields'),
      fieldDeleteConfirm: ref(false),
      selected_delete_record: ref({} as dynamicObj),
      profile_options: [
        { label: 'DEFAULT', value: 'DEFAULT' },
        { label: 'ZUGFeRD', value: 'Zugferd' },
      ],
      DEFAULT_ORG_UUID,
      data_type: ref([] as any),
      barcodeOptions: [
        { label: 'EAN2', value: 'EAN2' },
        { label: 'EAN5', value: 'EAN5' },
        { label: 'EAN8', value: 'EAN8' },
        { label: 'UPCE', value: 'UPCE' },
        { label: 'ISBN10', value: 'ISBN10' },
        { label: 'UPCA', value: 'UPCA' },
        { label: 'EAN13', value: 'EAN13' },
        { label: 'ISBN13', value: 'ISBN13' },
        { label: 'CODABAR', value: 'CODABAR' },
        { label: 'CODE39', value: 'CODE39' },
        { label: 'QRCODE', value: 'QRCODE' },
        { label: 'SQCODE', value: 'SQCODE' },
        { label: 'CODE93', value: 'CODE93' },
        { label: 'CODE128', value: 'CODE128' },
      ],
    };
  },
});
</script>

